// YCloud Inbound Parser + Rehost — Fase 2.2 + mídia persistente
// 1) Valida Bearer
// 2) Grava raw em ycloud_webhook_events (sempre)
// 3) Roteia por tipo:
//    - inbound_message → REHOST mídia pro Supabase Storage → INSERT wpp_conversations
//    - message status update → UPDATE wa_*_at
//    - template update → UPDATE ycloud_templates
// 4) Marca processed_at ou process_error
// 5) Sempre retorna 200

const SUPABASE_URL = '<<SUPABASE_URL>>';
const SERVICE_ROLE = '<<SUPABASE_SERVICE_ROLE>>';
const SHARED_SECRET = '<<SHARED_SECRET>>';
const STORAGE_BUCKET = 'whatsapp-media';

const sbHeaders = {
  apikey: SERVICE_ROLE,
  Authorization: 'Bearer ' + SERVICE_ROLE,
  'Content-Type': 'application/json',
};

const normalizeJid = (s) => String(s || '').trim().replace(/@s\.whatsapp\.net$|@g\.us$/i, '').replace(/\D/g, '');
const now = () => new Date().toISOString();
const safe = (s) => encodeURIComponent(String(s || ''));

// MIME → extensão
const extFromMime = (mime) => {
  const m = String(mime || '').split(';')[0].trim().toLowerCase();
  const map = {
    'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
    'video/mp4': 'mp4', 'video/webm': 'webm', 'video/quicktime': 'mov',
    'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac', 'audio/wav': 'wav',
    'application/pdf': 'pdf',
    'application/msword': 'doc',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'application/vnd.ms-excel': 'xls',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
    'application/zip': 'zip',
  };
  return map[m] || 'bin';
};

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};

// 1) Auth
const auth = headers.authorization || headers.Authorization || '';
if (auth !== 'Bearer ' + SHARED_SECRET) {
  return [{ json: { __status: 401, ok: false, error: 'unauthorized' } }];
}

const eventId = body.id || body.event_id || ('evt_' + Date.now());
const eventType = body.type || body.event || 'unknown';

// 2) Salva raw
let rawSaved = false;
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: SUPABASE_URL + '/rest/v1/ycloud_webhook_events',
    headers: { ...sbHeaders, Prefer: 'return=minimal' },
    body: { event_type: eventType, event_id: eventId, payload: body, received_at: now() },
    json: true,
  });
  rawSaved = true;
} catch (e) {
  console.error('Falha ao salvar raw:', e && e.message);
}

let processError = null;
let processedAction = null;

try {
  const isInboundMsg = /inbound_message|message\.received|whatsapp_message_received/i.test(eventType) || !!body.whatsappInboundMessage;
  const isStatusUpdate = /message\.updated|message_status|whatsapp_message_status/i.test(eventType) || (!!body.whatsappMessage && body.whatsappMessage.status);
  const isTemplateUpdate = /template\.updated|whatsapp_template/i.test(eventType) || !!body.whatsappTemplate;

  // ───── Mensagem recebida ─────
  if (isInboundMsg) {
    const msg = body.whatsappInboundMessage || body.data || body.message || body;
    const fromRaw = msg.from || msg.sender || '';
    const toRaw = msg.to || msg.phoneNumber || msg.recipient || msg.phoneNumberId || '';
    const wamid = msg.id || msg.messageId || msg.wamid || '';
    const msgType = (msg.type || 'text').toLowerCase();
    const ts = msg.timestamp || msg.createTime || now();

    let text = '';
    let mediaUrl = null;
    let mediaMime = null;
    let filename = null;

    if (msgType === 'text') {
      text = (msg.text && msg.text.body) || msg.body || '';
    } else if (msgType === 'image' || msgType === 'video' || msgType === 'document' || msgType === 'audio' || msgType === 'sticker') {
      const m = msg[msgType] || {};
      mediaUrl = m.link || m.url || m.fileUrl || null;
      mediaMime = m.mime_type || m.mimeType || m.contentType || null;
      filename = m.filename || m.name || null;
      text = m.caption || filename || ('[' + msgType + ']');
    } else if (msgType === 'location') {
      const loc = msg.location || {};
      text = '📍 ' + (loc.latitude || '') + ',' + (loc.longitude || '') + ' ' + (loc.name || '');
    } else {
      text = '[' + msgType + ']';
    }

    // Lookup empresa pelo phone_number_id
    const phoneId = String(toRaw).replace(/^\+/, '');
    const lookup = await this.helpers.httpRequest({
      method: 'GET',
      url: SUPABASE_URL + '/rest/v1/ycloud_phone_numbers?phone_number_id=eq.' + safe(phoneId) + '&select=id,company_id&limit=1',
      headers: sbHeaders,
      json: true,
    });

    if (!Array.isArray(lookup) || !lookup[0]) {
      processError = 'phone_not_found:' + phoneId;
    } else {
      const ycloudPhoneId = lookup[0].id;
      const company_id = lookup[0].company_id;
      const remoteJid = normalizeJid(fromRaw);

      // Auto-cria lead se não existe
      const leadCheck = await this.helpers.httpRequest({
        method: 'GET',
        url: SUPABASE_URL + '/rest/v1/leads?company_id=eq.' + company_id + '&remote_jid=eq.' + safe(remoteJid) + '&select=id&limit=1',
        headers: sbHeaders,
        json: true,
      });
      if (!Array.isArray(leadCheck) || !leadCheck[0]) {
        try {
          await this.helpers.httpRequest({
            method: 'POST',
            url: SUPABASE_URL + '/rest/v1/leads',
            headers: { ...sbHeaders, Prefer: 'return=minimal' },
            body: { company_id, remote_jid: remoteJid, lead_code: remoteJid, source: 'ycloud' },
            json: true,
          });
        } catch (_) {}
      }

      // ─── REHOST DA MÍDIA ───
      // Baixa do YCloud com X-API-Key e regrava no Supabase Storage,
      // garantindo que nada vai sumir mesmo se a YCloud apagar/expirar.
      let rehostedUrl = null;
      let rehostError = null;

      if (mediaUrl) {
        try {
          // Pega a api_key da empresa pra autenticar download
          const credLookup = await this.helpers.httpRequest({
            method: 'GET',
            url: SUPABASE_URL + '/rest/v1/company_ycloud_credentials?company_id=eq.' + company_id + '&select=api_key&limit=1',
            headers: sbHeaders,
            json: true,
          });
          const apiKey = (Array.isArray(credLookup) && credLookup[0] && credLookup[0].api_key) || null;

          // Tenta baixar (com X-API-Key se tiver, senao tenta direto)
          const dlHeaders = apiKey ? { 'X-API-Key': apiKey } : {};
          const fileResp = await this.helpers.httpRequest({
            method: 'GET',
            url: mediaUrl,
            headers: dlHeaders,
            encoding: 'arraybuffer',
            returnFullResponse: true,
          });
          const fileBuffer = fileResp.body;
          const respHeaders = fileResp.headers || {};
          const contentType = mediaMime || respHeaders['content-type'] || respHeaders['Content-Type'] || 'application/octet-stream';
          const ext = extFromMime(contentType);

          // Path no bucket: {company_id}/inbound/{msgType}/{wamid|timestamp}.{ext}
          const safeName = (wamid || ('msg_' + Date.now())).replace(/[^a-zA-Z0-9._-]/g, '_');
          const storagePath = company_id + '/inbound/' + msgType + '/' + safeName + '.' + ext;

          // Upload pro Storage
          await this.helpers.httpRequest({
            method: 'POST',
            url: SUPABASE_URL + '/storage/v1/object/' + STORAGE_BUCKET + '/' + storagePath,
            headers: {
              apikey: SERVICE_ROLE,
              Authorization: 'Bearer ' + SERVICE_ROLE,
              'Content-Type': contentType,
              'x-upsert': 'true',
              'Cache-Control': 'public, max-age=31536000',
            },
            body: fileBuffer,
            json: false,
          });

          // URL pública (bucket é público pra leitura)
          rehostedUrl = SUPABASE_URL + '/storage/v1/object/public/' + STORAGE_BUCKET + '/' + storagePath;
        } catch (e) {
          rehostError = (e && e.message) ? e.message.slice(0, 200) : String(e).slice(0, 200);
          console.error('Rehost falhou:', rehostError);
        }
      }

      // INSERT wpp_conversations
      await this.helpers.httpRequest({
        method: 'POST',
        url: SUPABASE_URL + '/rest/v1/wpp_conversations',
        headers: { ...sbHeaders, Prefer: 'return=minimal' },
        body: {
          company_id,
          remote_jid: remoteJid,
          provider: 'ycloud',
          ycloud_phone_number_id: ycloudPhoneId,
          message_id: wamid,
          from_me: false,
          message: text,
          message_type: msgType,
          // Prioriza URL rehospedada; fallback pra URL original (que pode ser temporária)
          media_url: rehostedUrl || mediaUrl,
          raw_payload: {
            ...body,
            __rehosted: !!rehostedUrl,
            __rehost_error: rehostError,
            __original_media_url: mediaUrl,
            __filename: filename,
            __mime: mediaMime,
          },
          created_at: ts,
        },
        json: true,
      });
      processedAction = 'inbound_message_inserted' + (rehostedUrl ? '+rehosted' : (mediaUrl ? '+rehost_failed' : ''));
    }
  }

  // ───── Status update ─────
  else if (isStatusUpdate) {
    const sm = body.whatsappMessage || body.data || body.message || body;
    const wamid = sm.id || sm.messageId || sm.wamid || '';
    const status = String(sm.status || '').toLowerCase();
    const ts = sm.timestamp || sm.updateTime || now();

    if (!wamid) {
      processError = 'status_missing_wamid';
    } else {
      const fieldMap = { sent: 'wa_sent_at', delivered: 'wa_delivered_at', read: 'wa_read_at' };
      const field = fieldMap[status];
      if (field) {
        await this.helpers.httpRequest({
          method: 'PATCH',
          url: SUPABASE_URL + '/rest/v1/wpp_conversations?message_id=eq.' + safe(wamid),
          headers: { ...sbHeaders, Prefer: 'return=minimal' },
          body: { [field]: ts },
          json: true,
        });
        processedAction = 'status_' + status;
      } else {
        processedAction = 'status_unhandled:' + status;
      }
    }
  }

  // ───── Template update ─────
  else if (isTemplateUpdate) {
    const tpl = body.whatsappTemplate || body.data || body.template || body;
    const name = tpl.name;
    const language = tpl.language || 'pt_BR';
    const status = String(tpl.status || 'PENDING').toUpperCase();
    const rejectionReason = tpl.rejectedReason || tpl.rejection_reason || null;

    if (name) {
      const updateBody = { status, rejection_reason: rejectionReason, last_synced_at: now() };
      if (status === 'APPROVED') updateBody.approved_at = now();

      await this.helpers.httpRequest({
        method: 'PATCH',
        url: SUPABASE_URL + '/rest/v1/ycloud_templates?name=eq.' + safe(name) + '&language=eq.' + safe(language),
        headers: { ...sbHeaders, Prefer: 'return=minimal' },
        body: updateBody,
        json: true,
      });
      processedAction = 'template_' + status.toLowerCase();
    } else {
      processError = 'template_missing_name';
    }
  }

  else {
    processedAction = 'logged_only:' + eventType;
  }
} catch (e) {
  processError = (e && e.message) ? e.message.slice(0, 500) : String(e).slice(0, 500);
}

// 4) Marca status do raw
if (rawSaved) {
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: SUPABASE_URL + '/rest/v1/ycloud_webhook_events?event_id=eq.' + safe(eventId),
      headers: { ...sbHeaders, Prefer: 'return=minimal' },
      body: processError ? { process_error: processError } : { processed_at: now() },
      json: true,
    });
  } catch (_) {}
}

return [{
  json: {
    __status: 200,
    ok: true,
    event_type: eventType,
    action: processedAction,
    error: processError,
  }
}];
